if (status !== 200 || !$json.id) {
  return [{ json: { ok: false, status: 401, error: $json.error_description || 'invalid_token', code: 'invalid_token' } }];
}
return [{ json: { ok: true, user_id: $json.id, email: $json.email || null } }];

const d = $json;
let row;
if (Array.isArray(d)) row = d[0];
else if (d && d.id) row = d;
else if (Array.isArray(d.body)) row = d.body[0];
else if (d && d.body && d.body.id) row = d.body;
if (!row) {
  return [{ json: { _status: 404, _body: { error: 'user_not_found', code: 'not_found' } } }];
}
return [{ json: { _status: 200, _body: { user_id: row.id, email: row.email } } }];

