if (status !== 200 || !$json.id) {
  return [{ json: { ok: false, status: 401, error: $json.error_description || 'invalid_token', code: 'invalid_token' } }];
}
return [{ json: { ok: true, user_id: $json.id, email: $json.email || null } }];

// Input: verify step returned { ok, user_id, email }.
// The original webhook payload sits on the Webhook node; its binary is named 'file'.
const user_id = $json.user_id;

const binary = $('upload::POST /uploads/room-photo').item.binary || {};
// n8n webhook v2 stores multipart files as field0, field1... so check both 'file' and 'file0'
const file = binary.file || binary.file0 || Object.values(binary)[0] || null;
if (!file) {
  return [{ json: { _error: { status: 400, body: { error: 'missing_file', code: 'invalid_file' } } } }];
}

const mime = (file.mimeType || '').toLowerCase();
const allowed = { 'image/jpeg': 'jpg', 'image/jpg': 'jpg', 'image/png': 'png' };
const ext = allowed[mime];
if (!ext) {
  return [{ json: { _error: { status: 400, body: { error: 'unsupported_media_type', code: 'invalid_file_type' } } } }];
}

const sizeBytes = Buffer.byteLength(file.data, 'base64');
if (sizeBytes > 10 * 1024 * 1024) {
  return [{ json: { _error: { status: 413, body: { error: 'file_too_large', code: 'file_too_large' } } } }];
}

// pure-JS UUID (no require('crypto') â€” blocked by n8n task-runner sandbox)
const upload_id = Array.from({length: 32}, () => (Math.random() * 16 | 0).toString(16)).join('');
const path = `${user_id}/${upload_id}`;

return [{
  json: { user_id, upload_id, ext, mime, path, storage_path: `user-uploads/${path}` },
  binary: { file }
}];

// Build the public URL for the uploaded object.
const row         = $('upload::Validate + name').item.json;
const user_id     = row.user_id;
const upload_id   = row.upload_id;
const path        = row.path;
const preview_url = `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/user-uploads/${path}`;
return [{ json: { user_id, upload_id, preview_url, storage_path: `user-uploads/${path}`, mime: row.mime } }];

const status = $json.statusCode || $json.status || 200;
if (status !== 200 || !$json.id) {
  return [{ json: { ok: false, status: 401, error: $json.error_description || 'invalid_token', code: 'invalid_token' } }];
}
return [{ json: { ok: true, user_id: $json.id, email: $json.email || null } }];

const webhookItem = $('ref-bulk::POST /uploads/reference/bulk').item.json;
const authItem    = $('ref-bulk::Verify JWT (HTTP)').item.json;
const _raw = webhookItem.body || {};
const body = (() => {
  const keys = Object.keys(_raw);
  if (keys.length === 1 && String(keys[0]).trimStart().startsWith('{')) {
    try { return JSON.parse(keys[0]); } catch(_) {}
  }
  return _raw;
})();

const user_id      = authItem.user_id;
const bearer_token = $('ref-bulk::POST /uploads/reference/bulk').item.json.headers?.authorization ||
                     $('ref-bulk::POST /uploads/reference/bulk').item.json.headers?.Authorization || '';

const VALID_STYLES = ['scandinavian','japandi','midcentury','traditional','industrial','boho'];
const VALID_ROOMS  = ['bedroom','kids room','dining room','kitchen','mandir','living room'];

const style_tag = (body.style_tag || '').trim();
const room_type = (body.room_type || '').trim();
const files     = Array.isArray(body.files) ? body.files : [];

if (!VALID_STYLES.includes(style_tag)) {
  return [{ json: { _error: { status: 400, body: { error: `invalid_style_tag: ${style_tag}`, code: 'invalid_request' } } } }];
}
if (!VALID_ROOMS.includes(room_type)) {
  return [{ json: { _error: { status: 400, body: { error: `invalid_room_type: ${room_type}`, code: 'invalid_request' } } } }];
}
if (files.length === 0) {
  return [{ json: { _error: { status: 400, body: { error: 'files_array_empty', code: 'invalid_request' } } } }];
}

// Rough total size check (~80 MB base64 limit)
const totalB64 = files.reduce((s, f) => s + (f.content_b64 || '').length, 0);
if (Math.floor(totalB64 * 3 / 4) > 80 * 1024 * 1024) {
  return [{ json: { _error: { status: 413, body: { error: 'payload_too_large_max_80mb', code: 'invalid_request' } } } }];
}

// Expand each file into its own item
return files.map((f, idx) => ({
  json: {
    file_b64:     f.content_b64,
    file_mime:    f.mime || 'image/jpeg',
    filename:     f.filename || `file_${idx}`,
    style_tag,
    room_type,
    user_id,
    bearer_token,
    file_index:   idx,
  }
}));

return [{
  json: {
    ...$json,
    _cfg: {
      supabase_url:    'https://uzghfpxboktnbcbbthns.supabase.co',
      supabase_key:    '__REDACTED_SUPABASE_SERVICE_KEY__',
      gemini_key:      '__REDACTED_GEMINI_API_KEY__',
      openrouter_key:  '__REDACTED_OPENROUTER_API_KEY__',
