      admin_token:     '__REDACTED_ADMIN_TOKEN__'
    }
  },
  binary: $input.first().binary || {}
}];

const status = $json.statusCode || $json.status || 200;
if (status !== 200 || !$json.id) {
  return [{ json: { ok: false, status: 401, error: $json.error_description || 'invalid_token', code: 'invalid_token' } }];
}
return [{ json: { ok: true, user_id: $json.id, email: $json.email || null } }];

const _raw = $('edit::POST /generate/edit').item.json.body || {};
const body = (() => {
  const keys = Object.keys(_raw);
  if (keys.length === 1 && String(keys[0]).trimStart().startsWith('{')) {
    try { return JSON.parse(keys[0]); } catch (_) {}
  }
  return _raw;
})();
const user_id = $json.user_id;

const generation_id = (body.generation_id || '').toString().trim();
const instruction   = (body.instruction   || '').toString().trim();
const session_id    = body.session_id ? body.session_id.toString() : null;

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRe.test(generation_id)) {
  return [{ json: { _error: { status: 400, body: { error: 'invalid_generation_id', code: 'invalid_request' } } } }];
}
if (!instruction) {
  return [{ json: { _error: { status: 400, body: { error: 'missing_instruction', code: 'invalid_request' } } } }];
}

return [{ json: { user_id, generation_id, instruction, session_id, started_at_ms: Date.now() } }];

const rows   = Array.isArray($json) ? $json : ($json.body || []);
const parent = rows[0];
const ctx    = $('edit::Validate body').item.json;
if (!parent) {
  return [{ json: { _error: { status: 404, body: { error: 'parent_not_found', code: 'not_found' } } } }];
}
if (!parent.output_image_path) {
  return [{ json: { _error: { status: 400, body: { error: 'parent_output_missing', code: 'invalid_state' } } } }];
}

return [{ json: {
  ...ctx,
  parent,
  parent_output_url: `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${parent.output_image_path}`
} }];

const depth = typeof $json === 'number' ? $json : parseInt($json, 10) || 0;
const ctx   = $('edit::Shape parent').item.json;
// Parent itself consumes depth N ancestors; this new edit adds 1 more.
// Cap at 6 total edits below a root.
if (depth + 1 > 6) {
  return [{ json: { _error: { status: 400, body: { error: 'edit_chain_cap_exceeded', code: 'edit_cap_exceeded' } } } }];
}
return [{ json: { ...ctx, chain_depth: depth } }];

const ctx = $('edit::Check cap').item.json;
const bin = $input.item.binary.image;
const template = `You are editing an interior design photograph.

TASK: Apply ONLY the specific change requested below. Do not modify any other
element of the image. Preserve all geometry, lighting, and unaffected objects
exactly.

REQUESTED CHANGE: {instruction}
`;
const prompt = template.replace('{instruction}', ctx.instruction);

const openrouter_body = {
  model: ctx.model || 'google/gemini-3.1-flash-image-preview',
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: prompt },
      { type: 'image_url', image_url: { url: `data:${bin.mimeType || 'image/png'};base64,${bin.data}` } }
    ]
  }]
};
return [{ json: { ...ctx, prompt, openrouter_body } }];

const rows  = Array.isArray($json) ? $json : ($json.body || []);
const model = (rows[0] && rows[0].value) || 'gemini-3.1-flash-image-preview';
const ctx   = $('edit::Build Gemini request').item.json;
return [{ json: { ...ctx, model } }];

const ctx  = $('edit::Attach model').item.json;
const resp = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || [];
const parts   = Array.isArray(content) ? content : [];
const imgPart = parts.find(p => p.type === 'image_url');
if (!imgPart) {
  return [{ json: { _error: { status: 502, body: { error: 'no_image_in_response', code: 'upstream_error' } } } }];
}
const dataUrl = imgPart.image_url && imgPart.image_url.url;
const match   = dataUrl && dataUrl.match(/^data:([^;]+);base64,(.+)$/s);
if (!match) {
  return [{ json: { _error: { status: 502, body: { error: 'invalid_image_data_url', code: 'upstream_error' } } } }];
}
const mime = match[1];
const b64  = match[2];
const latency_ms = Date.now() - ctx.started_at_ms;

return [{
  json: {
    user_id:             ctx.user_id,
    session_id:          ctx.session_id,
    parent_generation_id: ctx.parent.id,
    kind:                'edit',
    input_image_path:    ctx.parent.output_image_path,
    room_type:           ctx.parent.room_type,
    style_tag:           ctx.parent.style_tag,
    reference_image_ids: ctx.parent.reference_image_ids,
    prompt:              ctx.prompt,
    model_config:        'A',
    model_id:            ctx.model,
    latency_ms,
    cost_usd:            0
  },
  binary: { output_png: { data: b64, mimeType: mime, fileExtension: 'png', fileName: 'output.png' } }
}];

