    try { return JSON.parse(keys[0]); } catch (_) {}
  }
  return _raw;
})();
const user_id = $json.user_id;

const parent_generation_id = (body.parent_generation_id || body.generation_id || '').toString().trim();
const session_id = body.session_id ? body.session_id.toString() : null;

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRe.test(parent_generation_id)) {
  return [{ json: { _error: { status: 400, body: { error: 'invalid_parent_generation_id', code: 'invalid_request' } } } }];
}

return [{ json: { user_id, parent_generation_id, session_id, started_at_ms: Date.now() } }];

const rows   = Array.isArray($json) ? $json : ($json.body || []);
const parent = rows[0];
const ctx    = $('commit::Validate body').item.json;
if (!parent) {
  return [{ json: { _error: { status: 404, body: { error: 'parent_not_found', code: 'not_found' } } } }];
}
if (!parent.output_image_path || !parent.input_image_path) {
  return [{ json: { _error: { status: 400, body: { error: 'parent_incomplete', code: 'invalid_state' } } } }];
}
// Walk up the chain to the root to recover the original upload. Commit should
// render from the original room photo, not from an intermediate edit output.
// parent.input_image_path on an edit points at the previous generation's output;
// on a draft it points at user-uploads/<uid>/<upload_id>. For commit we want
// to combine: the ORIGINAL upload + the latest parent output + reference images.
return [{ json: {
  ...ctx,
  parent,
  parent_input_url:  `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${parent.input_image_path}`,
  parent_output_url: `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${parent.output_image_path}`
} }];

// Build ordered fetch list: parent input (original room), then parent output,
// then each reference image in the order stored on the parent row.
const ctx   = $('commit::Shape parent').item.json;
const refs  = Array.isArray($json) ? $json : ($json.body || []);
const byId  = {};
refs.forEach(r => { byId[r.id] = r.source_url; });

const urls = [ctx.parent_input_url, ctx.parent_output_url];
for (const id of (ctx.parent.reference_image_ids || [])) {
  if (byId[id]) urls.push(byId[id]);
}
return urls.map((url, i) => ({ json: { ...ctx, idx: i, fetch_url: url } }));

const items = $input.all();
items.sort((a, b) => a.json.idx - b.json.idx);
const parts = items.map(it => ({
  inline_data: {
    mime_type: it.binary.image.mimeType || 'image/png',
    data:      it.binary.image.data
  }
}));
return [{ json: { ...items[0].json, image_parts: parts } }];

const rows  = Array.isArray($json) ? $json : ($json.body || []);
const model = (rows[0] && rows[0].value) || 'google/gemini-3.1-flash-image-preview';
const ctx   = $('commit::Collect image parts').item.json;

const template = `You are an interior design rendering engine.

TASK: Generate a photorealistic image of the SAME room shown in the first input
image, redesigned in the style of the reference images provided.

HARD CONSTRAINTS:
- Preserve the input room's geometry exactly: wall positions, window positions
  and sizes, door positions, ceiling height.
- Preserve lighting direction from the input photo.
- Use furniture, materials, colors, and styling cues from the reference images.
- Output must be photorealistic, no illustrations or cartoons.
- Do not add text, watermarks, logos, or signatures.
- Do not add people.

STYLE: {style_tag}
ROOM TYPE: {room_type}

OUTPUT QUALITY: Maximum resolution and detail. This is the final deliverable.
`;

const prompt = template
  .replace('{style_tag}', ctx.parent.style_tag || '')
  .replace('{room_type}', ctx.parent.room_type || '');

const openrouter_body = {
  model,
  messages: [{
    role: 'user',
    content: [{ type: 'text', text: prompt }, ...(ctx.image_parts || [])]
  }]
};

return [{ json: { ...ctx, model, prompt, openrouter_body } }];

const ctx  = $('commit::Build Gemini request').item.json;
const resp = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || [];
const parts   = Array.isArray(content) ? content : [];
const imgPart = parts.find(p => p.type === 'image_url');
if (!imgPart) {
  return [{ json: { _error: { status: 502, body: { error: 'no_image_in_response', code: 'upstream_error' } } } }];
}
const dataUrl = imgPart.image_url && imgPart.image_url.url;
const match   = dataUrl && dataUrl.match(/^data:([^;]+);base64,(.+)$/s);
if (!match) {
  return [{ json: { _error: { status: 502, body: { error: 'invalid_image_data_url', code: 'upstream_error' } } } }];
}
const mime = match[1];
const b64  = match[2];
const latency_ms = Date.now() - ctx.started_at_ms;

return [{
  json: {
    user_id:             ctx.user_id,
    session_id:          ctx.session_id,
    parent_generation_id: ctx.parent.id,
    kind:                'commit',
    input_image_path:    ctx.parent.input_image_path,
    room_type:           ctx.parent.room_type,
    style_tag:           ctx.parent.style_tag,
    reference_image_ids: ctx.parent.reference_image_ids,
    prompt:              ctx.prompt,
    model_config:        'A',
    model_id:            ctx.model,
    latency_ms,
    cost_usd:            0
  },
  binary: { output_png: { data: b64, mimeType: mime, fileExtension: 'png', fileName: 'output.png' } }
}];

